CREATE TABLE dbo.enrollment(hash varchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY,expires bigint NOT NULL);
CREATE TABLE dbo.endpoints(id varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY,credential_hash varchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE,machine nvarchar(255) NOT NULL,version nvarchar(64) NOT NULL,health nvarchar(512) NOT NULL,last_seen bigint NOT NULL,revoked bigint NOT NULL DEFAULT 0);
CREATE TABLE dbo.events(sequence bigint IDENTITY(1,1) NOT NULL PRIMARY KEY,endpoint varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES dbo.endpoints(id),event_id varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL,received bigint NOT NULL,payload nvarchar(max) COLLATE Latin1_General_100_BIN2 NOT NULL,UNIQUE(endpoint,event_id));
CREATE INDEX events_received ON dbo.events(received,endpoint);
CREATE TABLE dbo.audit(sequence bigint IDENTITY(1,1) NOT NULL PRIMARY KEY,time bigint NOT NULL,action nvarchar(max) NOT NULL,subject nvarchar(max) NOT NULL);
CREATE TABLE dbo.reports(id varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY,owner nvarchar(450) NOT NULL,created bigint NOT NULL,payload nvarchar(max) NOT NULL);
CREATE INDEX reports_owner_created ON dbo.reports(owner,created DESC,id DESC);
CREATE TABLE dbo.endpoint_groups(id varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY,name nvarchar(160) COLLATE Latin1_General_100_CI_AS NOT NULL UNIQUE,revision bigint NOT NULL,payload nvarchar(max) NOT NULL);
CREATE TABLE dbo.policy_revisions(revision bigint IDENTITY(1,1) NOT NULL PRIMARY KEY,group_id varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES dbo.endpoint_groups(id),created bigint NOT NULL,actor nvarchar(450) NOT NULL,payload nvarchar(max) NOT NULL);
CREATE TABLE dbo.endpoint_groups_binding(endpoint varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY REFERENCES dbo.endpoints(id),group_id varchar(32) COLLATE Latin1_General_100_BIN2 REFERENCES dbo.endpoint_groups(id),applied_revision bigint,reported bigint);
CREATE INDEX group_members ON dbo.endpoint_groups_binding(group_id);
CREATE TABLE dbo.incidents(id varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY,title nvarchar(200) NOT NULL,severity nvarchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL,status nvarchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL,version bigint NOT NULL,created bigint NOT NULL,updated bigint NOT NULL,creator nvarchar(450) NOT NULL);
CREATE TABLE dbo.incident_events(incident varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES dbo.incidents(id),event_sequence bigint NOT NULL REFERENCES dbo.events(sequence),PRIMARY KEY(incident,event_sequence));
CREATE TABLE dbo.incident_notes(sequence bigint IDENTITY(1,1) NOT NULL PRIMARY KEY,incident varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES dbo.incidents(id),time bigint NOT NULL,actor nvarchar(450) NOT NULL,note nvarchar(max) NOT NULL);
CREATE INDEX incidents_updated ON dbo.incidents(updated DESC,id);
CREATE INDEX incident_notes_case ON dbo.incident_notes(incident,sequence);
CREATE TABLE dbo.response_commands(id varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY,endpoint varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES dbo.endpoints(id),payload nvarchar(max) NOT NULL,status nvarchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL,result nvarchar(max),expires bigint NOT NULL,reported bigint);
CREATE INDEX response_commands_pending ON dbo.response_commands(endpoint,status,expires);
CREATE TABLE dbo.incident_assignments(incident varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY REFERENCES dbo.incidents(id),owner nvarchar(450));
CREATE TABLE dbo.report_schedules(id varchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL PRIMARY KEY,owner nvarchar(450) NOT NULL,name nvarchar(100) NOT NULL,days int NOT NULL,hours int NOT NULL,next bigint NOT NULL,enabled bigint NOT NULL,version bigint NOT NULL,last_report varchar(32),last_error nvarchar(512));
CREATE INDEX report_schedules_due ON dbo.report_schedules(enabled,next);
